import json
import re
import sys
import os

def parse_script(text: str):
    lines = text.splitlines()
    nodes = []
    edges = []

    # Identify blocks
    # A block starts with [ID]
    blocks = []
    current_block_lines = []

    for line in lines:
        line = line.strip()
        if not line:
            continue

        if line.startswith("[") and line.endswith("]"):
            if current_block_lines:
                blocks.append(current_block_lines)
            current_block_lines = [line]
        else:
            if current_block_lines:
                current_block_lines.append(line)

    if current_block_lines:
        blocks.append(current_block_lines)

    for block in blocks:
        header = block[0]
        block_id = header[1:-1] # Remove [ and ]

        if len(block) < 2:
            continue # Empty block

        content_lines = block[1:]

        # Determine type based on first line
        first = content_lines[0]

        # Check if choice (starts with number dot)
        if re.match(r'^\d+\.', first):
            # Choice Block
            nodes.append({
                "id": block_id,
                "text": "",
                "speaker": "",
                "type": "choice"
            })

            # Edges
            for l in content_lines:
                m = re.match(r'^\d+\.\s*(.+)\s*->\s*(.+)$', l)
                if m:
                    choice_text = m.group(1).strip()
                    target = m.group(2).strip()
                    edges.append({
                        "from": block_id,
                        "to": target,
                        "text": choice_text
                    })
        else:
            # Line Block
            l = content_lines[0]
            m = re.match(r'^([^:]+):\s*(.+)\s*->\s*(.+)$', l)
            if m:
                speaker = m.group(1).strip()
                text_val = m.group(2).strip()
                target = m.group(3).strip()

                nodes.append({
                    "id": block_id,
                    "text": text_val,
                    "speaker": speaker,
                    "type": "line"
                })

                edges.append({
                    "from": block_id,
                    "to": target,
                    "text": None
                })

    return {"nodes": nodes, "edges": edges}

def validate_graph(graph):
    nodes = graph['nodes']
    edges = graph['edges']

    node_ids = set(n['id'] for n in nodes)

    if not nodes:
        return

    # 1. Reachability from first node
    start_node = nodes[0]['id']
    reachable = set()
    queue = [start_node]
    reachable.add(start_node)

    edge_map = {}
    for e in edges:
        if e['from'] not in edge_map:
            edge_map[e['from']] = []
        edge_map[e['from']].append(e['to'])

    while queue:
        curr = queue.pop(0)
        if curr in edge_map:
            for target in edge_map[curr]:
                if target in node_ids and target not in reachable:
                    reachable.add(target)
                    queue.append(target)

    unreachable = node_ids - reachable
    if unreachable:
        print(f"Warning: Unreachable nodes found: {unreachable}")

    # 2. Edge targets exist (except 'End')
    for e in edges:
        target = e['to']
        if target not in node_ids and target != "End":
            print(f"Warning: Edge target '{target}' does not exist.")

def generate_dot(graph):
    lines = ["digraph Dialogue {"]
    lines.append("  node [shape=box];")

    for n in graph['nodes']:
        lbl = n['id']
        # Escape quotes for label
        if n['type'] == 'line':
            text = n['text'].replace('"', '\\"')
            lbl_text = f"{n['speaker']}: {text}"
            if len(lbl_text) > 50:
                 lbl_text = lbl_text[:47] + "..."
            lbl = lbl_text
        elif n['type'] == 'choice':
            lbl = f"Choice: {n['id']}"

        lines.append(f'  "{n["id"]}" [label="{lbl}"];')

    for e in graph['edges']:
        label_attr = ""
        if e.get('text'):
            txt = e['text'].replace('"', '\\"')
            if len(txt) > 30:
                txt = txt[:27] + "..."
            label_attr = f' [label="{txt}"]'
        lines.append(f'  "{e["from"]}" -> "{e["to"]}"{label_attr};')

    lines.append("}")
    return "\n".join(lines)

if __name__ == "__main__":
    input_path = "/app/script.txt"
    output_json = "/app/dialogue.json"
    output_dot = "/app/dialogue.dot"

    try:
        with open(input_path, 'r') as f:
            text = f.read()

        graph = parse_script(text)

        validate_graph(graph)

        with open(output_json, 'w') as f:
            json.dump(graph, f, indent=2)

        dot_content = generate_dot(graph)
        with open(output_dot, 'w') as f:
            f.write(dot_content)

        print("Parsing complete.")

    except Exception as e:
        print(f"Error: {e}")

